// >>> EDIT THIS: must match the "Verify Token" you set in the Meta App dashboard
const VERIFY_TOKEN = 'my-secret-verify-token';

const q = $input.first().json.query || {};
const mode = q['hub.mode'];
const token = q['hub.verify_token'];
const challenge = q['hub.challenge'];

if (mode === 'subscribe' && token === VERIFY_TOKEN) {
  return [{ json: { ok: true, challenge: challenge || '' } }];
}
return [{ json: { ok: false, challenge: '' } }];

// =======================================================================
// CONFIG - edit these values for your setup, everything else reads them
// =======================================================================
const CONFIG = {
  whatsappToken: 'PASTE_YOUR_WHATSAPP_CLOUD_API_PERMANENT_TOKEN_HERE',
  phoneNumberId: 'PASTE_YOUR_WHATSAPP_PHONE_NUMBER_ID_HERE',
  graphApiVersion: 'v20.0',
  ollamaUrl: 'http://localhost:11434/api/chat',
  ollamaModel: 'llama3.1:8b',
  dataDir: '/data',
  adminEmail: 'admin@smartstore.com',
  rateLimitMax: 8,          // max messages per phone per rate limit window
  rateLimitWindowMs: 60000, // 1 minute
  currency: 'USD'
};

const body = $input.first().json.body || {};

try {
  const entry = (body.entry && body.entry[0]) || null;
  const change = (entry && entry.changes && entry.changes[0]) || null;
  const value = (change && change.value) || null;

  if (!value) {
    return [{ json: { skip: true, reason: 'no_value', config: CONFIG } }];
  }

  // Statuses (delivered/read receipts) have no "messages" array - ignore them
  const messages = value.messages;
  if (!messages || messages.length === 0) {
    return [{ json: { skip: true, reason: 'status_update', config: CONFIG } }];
  }

  const msg = messages[0];
  const contact = (value.contacts && value.contacts[0]) || {};
  const fromPhone = msg.from || contact.wa_id || '';
  const messageId = msg.id || ('no-id-' + Date.now());
  const timestamp = msg.timestamp || String(Math.floor(Date.now() / 1000));
  const profileName = (contact.profile && contact.profile.name) || 'Customer';

  let text = '';
  let messageType = msg.type || 'unknown';

  if (msg.type === 'text' && msg.text && typeof msg.text.body === 'string') {
    text = msg.text.body;
  } else if (msg.type === 'button' && msg.button && msg.button.text) {
    text = msg.button.text;
  } else if (msg.type === 'interactive' && msg.interactive) {
    if (msg.interactive.button_reply) text = msg.interactive.button_reply.title || '';
    else if (msg.interactive.list_reply) text = msg.interactive.list_reply.title || '';
  } else {
    // images, audio, location, documents, unsupported types etc.
    text = '';
  }

  if (!fromPhone) {
    return [{ json: { skip: true, reason: 'no_phone', config: CONFIG } }];
  }

  return [{
    json: {
      skip: false,
      config: CONFIG,
      phone: fromPhone,
      messageId,
      timestamp,
      profileName,
      messageType,
      text: (text || '').trim(),
      textUpper: (text || '').trim().toUpperCase()
    }
  }];
} catch (err) {
  return [{ json: { skip: true, reason: 'parse_error', error: err.message, config: CONFIG } }];
}

const item = $input.first().json;
const staticData = $getWorkflowStaticData('global');

if (!staticData.processedIds) staticData.processedIds = [];
if (!staticData.rateLimits) staticData.rateLimits = {};
if (!staticData.sessions) staticData.sessions = {};

const phone = item.phone;
const messageId = item.messageId;
const now = Date.now();
const cfg = item.config;

// ---- Duplicate detection (WhatsApp can resend the same webhook) ----
let isDuplicate = staticData.processedIds.includes(messageId);
if (!isDuplicate) {
  staticData.processedIds.push(messageId);
  // keep memory bounded
  if (staticData.processedIds.length > 500) {
    staticData.processedIds = staticData.processedIds.slice(-500);
  }
}

// ---- Rate limiting per phone number ----
let isRateLimited = false;
if (!isDuplicate) {
  const windowMs = (cfg && cfg.rateLimitWindowMs) || 60000;
  const maxMsgs = (cfg && cfg.rateLimitMax) || 8;
  const history = (staticData.rateLimits[phone] || []).filter(ts => now - ts < windowMs);
  history.push(now);
  staticData.rateLimits[phone] = history;
  isRateLimited = history.length > maxMsgs;
}

// ---- Session (per phone) ----
if (!staticData.sessions[phone]) {
  staticData.sessions[phone] = {
    state: 'idle',
    cart: [],
    appliedCoupon: null,
    lastIntent: null,
    handoffToHuman: false,
    createdAt: now
  };
}
const session = staticData.sessions[phone];
session.lastSeen = now;

return [{
  json: {
    ...item,
    isDuplicate,
    isRateLimited,
    session
  }
}];

const fs = require('fs');
const path = require('path');
const DATA_DIR = '/data';

function splitCSVLine(line) {
  const result = [];
  let cur = '';
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') {
      if (inQuotes && line[i + 1] === '"') { cur += '"'; i++; }
      else { inQuotes = !inQuotes; }
    } else if (c === ',' && !inQuotes) {
      result.push(cur); cur = '';
    } else {
      cur += c;
    }
  }
  result.push(cur);
  return result.map(v => v.trim());
}

function parseCSV(content) {
  if (!content) return [];
  const lines = content.split(/\r?\n/).filter(l => l.length > 0);
  if (lines.length === 0) return [];
  const headers = splitCSVLine(lines[0]);
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const vals = splitCSVLine(lines[i]);
    const obj = {};
    headers.forEach((h, idx) => { obj[h] = vals[idx] !== undefined ? vals[idx] : ''; });
    rows.push(obj);
  }
  return rows;
}

function toCSVValue(v) {
  v = (v === undefined || v === null) ? '' : String(v);
  if (v.includes(',') || v.includes('"') || v.includes('\n')) {
    v = '"' + v.replace(/"/g, '""') + '"';
  }
  return v;
}

function rowsToCSV(rows, headers) {
  const lines = [headers.join(',')];
  rows.forEach(r => { lines.push(headers.map(h => toCSVValue(r[h])).join(',')); });
  return lines.join('\n') + '\n';
}

function readTable(filename) {
  try {
    const filePath = path.join(DATA_DIR, filename);
    if (!fs.existsSync(filePath)) return { rows: [], headers: [] };
    const content = fs.readFileSync(filePath, 'utf8');
    const rows = parseCSV(content);
    const headers = rows.length > 0 ? Object.keys(rows[0]) : (content.split(/\r?\n/)[0] || '').split(',').map(h => h.trim());
    return { rows, headers };
  } catch (e) {
    return { rows: [], headers: [], error: e.message };
  }
}

function writeTable(filename, rows, headers) {
  try {
    const filePath = path.join(DATA_DIR, filename);
    fs.writeFileSync(filePath, rowsToCSV(rows, headers), 'utf8');
    return true;
  } catch (e) {
    return false;
  }
}

function appendLog(filename, row, headers) {
  try {
    const filePath = path.join(DATA_DIR, filename);
    let existed = fs.existsSync(filePath);
    const line = headers.map(h => toCSVValue(row[h])).join(',') + '\n';
    if (!existed) {
      fs.writeFileSync(filePath, headers.join(',') + '\n' + line, 'utf8');
    } else {
      fs.appendFileSync(filePath, line, 'utf8');
    }
    return true;
  } catch (e) {
    return false;
  }
}

const item = $input.first().json;
const text = item.text || '';
const textUpper = item.textUpper || '';
const session = item.session;

// ---- Load all reference tables (cheap - small CSVs) ----
const products = readTable('products.csv').rows;
const faqs = readTable('faqs.csv').rows;
const orders = readTable('orders.csv').rows;
const tracking = readTable('tracking.csv').rows;
const coupons = readTable('coupons.csv').rows;
const shipping = readTable('shipping.csv').rows;
const settings = readTable('settings.csv').rows;

const settingsMap = {};
settings.forEach(s => { settingsMap[s['Setting']] = s['Value']; });

let route = 'fallback';
let routeData = {};

// ---------------- Command detection (deterministic, highest priority) ----------------
if (/^(MENU|HI|HELLO|HEY|START|HI THERE)$/i.test(text.trim())) {
  route = 'menu';

} else if (/^TRACK\s+/i.test(text.trim())) {
  const orderId = text.trim().split(/\s+/)[1] || '';
  route = 'track';
  routeData = { orderId: orderId.toUpperCase() };

} else if (/^(HUMAN|AGENT|SUPPORT|TALK TO (A )?(HUMAN|AGENT))$/i.test(text.trim())) {
  route = 'human';

} else if (/^(CART\s+ADD|ADD)\s+/i.test(text.trim())) {
  const parts = text.trim().split(/\s+/);
  const isCartAdd = /^CART$/i.test(parts[0]);
  const pid = isCartAdd ? parts[2] : parts[1];
  const qtyRaw = isCartAdd ? parts[3] : parts[2];
  const qty = parseInt(qtyRaw, 10);
  route = 'cart_add';
  routeData = { productId: (pid || '').toUpperCase(), qty: isNaN(qty) || qty < 1 ? 1 : qty };

} else if (/^(CART|VIEW CART|MY CART)$/i.test(text.trim())) {
  route = 'cart_view';

} else if (/^(CLEAR CART|EMPTY CART)$/i.test(text.trim())) {
  route = 'cart_clear';

} else if (/^CHECKOUT/i.test(text.trim())) {
  route = 'checkout';

} else if (/^COUPON\s+/i.test(text.trim())) {
  const code = text.trim().split(/\s+/)[1] || '';
  route = 'coupon';
  routeData = { code: code.toUpperCase() };

} else if (text.trim().length === 0) {
  // non-text message (image, sticker, location, etc.)
  route = 'fallback';

} else {
  // ---------------- Not a command: try FAQ keyword match first ----------------
  const lowerText = text.toLowerCase();
  let bestFaq = null;
  let bestScore = 0;
  faqs.forEach(f => {
    const kws = (f['Keywords'] || '').split('|').map(k => k.trim().toLowerCase()).filter(Boolean);
    let score = 0;
    kws.forEach(k => { if (k && lowerText.includes(k)) score++; });
    if (score > bestScore) { bestScore = score; bestFaq = f; }
  });

  if (bestFaq && bestScore > 0) {
    route = 'faq';
    routeData = { matchedFaq: bestFaq };
  } else {
    // ---------------- Try product/category keyword match ----------------
    const productWords = new Set();
    products.forEach(p => {
      (p['Category'] || '').toLowerCase().split(/\s+/).forEach(w => w && productWords.add(w));
      (p['Brand'] || '').toLowerCase().split(/\s+/).forEach(w => w && productWords.add(w));
      (p['Product Name'] || '').toLowerCase().split(/\s+/).forEach(w => w && productWords.add(w));
    });
    const shoppingHints = ['buy', 'price', 'cost', 'recommend', 'looking for', 'show me', 'have', 'available', 'stock', 'compare'];
    const words = lowerText.split(/\W+/).filter(Boolean);
    const hasProductWord = words.some(w => productWords.has(w));
    const hasShoppingHint = shoppingHints.some(h => lowerText.includes(h));

    if (hasProductWord || hasShoppingHint) {
      route = 'product_search';
    } else {
      route = 'fallback';
    }
  }
}

return [{
  json: {
    ...item,
    route,
    routeData,
    tables: { products, faqs, orders, tracking, coupons, shipping },
    settingsMap
  }
}];

