return [{ json: { ...item, replyText: text, needsHumanEscalation: true } }];

const item = $input.first().json;
const { productId, qty } = item.routeData || {};
const products = item.tables.products || [];

if (!productId) {
  return [{ json: { ...item, replyText: "Please use the format: CART ADD <ProductID> <Qty>, e.g. CART ADD P003 1" } }];
}

const product = products.find(p => (p['Product ID'] || '').toUpperCase() === productId && p['Status'] === 'Active');
if (!product) {
  return [{ json: { ...item, replyText: `I couldn't find an active product with ID ${productId}. Type MENU or search by name to see options.` } }];
}

const stock = parseInt(product['Stock'], 10) || 0;

// how many of this product are already in the cart
const existingQty = item.session.cart
  .filter(c => c.productId === productId)
  .reduce((sum, c) => sum + c.qty, 0);

if (existingQty + qty > stock) {
  return [{ json: { ...item, replyText: `Sorry, only ${stock} unit(s) of ${product['Product Name']} are in stock (you already have ${existingQty} in your cart).` } }];
}

item.session.cart.push({
  productId,
  name: product['Product Name'],
  price: parseFloat(product['Final Price']) || parseFloat(product['Price']) || 0,
  qty
});

const text = `Added ${qty} x ${product['Product Name']} to your cart ✅\nType CART to view your cart or CHECKOUT to place your order.`;
return [{ json: { ...item, replyText: text } }];

const item = $input.first().json;
const cart = item.session.cart || [];
const currency = (item.settingsMap && item.settingsMap['Currency']) || 'USD';

if (cart.length === 0) {
  return [{ json: { ...item, replyText: "Your cart is empty. Search for a product or type MENU to see options." } }];
}

let total = 0;
let lines = cart.map(c => {
  const lineTotal = c.price * c.qty;
  total += lineTotal;
  return `${c.qty} x ${c.name} - ${currency} ${lineTotal.toFixed(2)}`;
});

let couponLine = '';
if (item.session.appliedCoupon) {
  const disc = item.session.appliedCoupon.discountPct;
  const discountAmt = total * (disc / 100);
  couponLine = `\nCoupon ${item.session.appliedCoupon.code}: -${currency} ${discountAmt.toFixed(2)}`;
  total -= discountAmt;
}

const text = `🛒 Your Cart:\n${lines.join('\n')}${couponLine}\n\nTotal: ${currency} ${total.toFixed(2)}\n\nType CHECKOUT to place your order.`;
return [{ json: { ...item, replyText: text } }];

const item = $input.first().json;
item.session.cart = [];
item.session.appliedCoupon = null;
return [{ json: { ...item, replyText: "Your cart has been cleared." } }];

const item = $input.first().json;
const code = (item.routeData && item.routeData.code) || '';
const coupons = item.tables.coupons || [];
const currency = (item.settingsMap && item.settingsMap['Currency']) || 'USD';

if (!code) {
  return [{ json: { ...item, replyText: "Please use the format: COUPON <CODE>, e.g. COUPON WELCOME10" } }];
}

const coupon = coupons.find(c => (c['Coupon Code'] || '').toUpperCase() === code);
if (!coupon || coupon['Status'] !== 'Active') {
  return [{ json: { ...item, replyText: `Coupon code ${code} is not valid.` } }];
}

const expiry = new Date(coupon['Expiry']);
const now = new Date();
if (!isNaN(expiry.getTime()) && expiry < now) {
  return [{ json: { ...item, replyText: `Coupon code ${code} has expired.` } }];
}

const cartTotal = (item.session.cart || []).reduce((sum, c) => sum + c.price * c.qty, 0);
const minOrder = parseFloat(coupon['Minimum Order']) || 0;

if (cartTotal < minOrder) {
  return [{ json: { ...item, replyText: `Coupon ${code} requires a minimum order of ${currency} ${minOrder}. Your current cart total is ${currency} ${cartTotal.toFixed(2)}.` } }];
}

const discountPct = parseFloat((coupon['Discount'] || '0').replace('%', '')) || 0;
item.session.appliedCoupon = { code: coupon['Coupon Code'], discountPct };

return [{ json: { ...item, replyText: `Coupon ${code} applied! You get ${discountPct}% off. Type CART to see your updated total.` } }];

