const item = $input.first().json;
const cart = item.session.cart || [];
const currency = (item.settingsMap && item.settingsMap['Currency']) || 'USD';

if (cart.length === 0) {
  return [{ json: { ...item, replyText: "Your cart is empty. Add a product first, e.g. CART ADD P003 1", sendAdminEmail: false } }];
}

// Re-read products fresh (avoid selling stock that changed since the session started)
const { rows: products, headers: productHeaders } = readTable('products.csv');

// ---- Validate stock for every cart line before committing anything ----
let insufficient = [];
cart.forEach(c => {
  const p = products.find(p => (p['Product ID'] || '').toUpperCase() === c.productId);
  const stock = p ? (parseInt(p['Stock'], 10) || 0) : 0;
  if (!p || stock < c.qty) {
    insufficient.push(`${c.name} (only ${stock} left)`);
  }
});

if (insufficient.length > 0) {
  return [{
    json: {
      ...item,
      replyText: `Sorry, we can't complete checkout - insufficient stock for: ${insufficient.join(', ')}. Type CART to review your cart.`,
      sendAdminEmail: false
    }
  }];
}

// ---- Compute totals ----
let subtotal = cart.reduce((sum, c) => sum + c.price * c.qty, 0);
let discountAmt = 0;
let couponCode = '';
if (item.session.appliedCoupon) {
  couponCode = item.session.appliedCoupon.code;
  discountAmt = subtotal * (item.session.appliedCoupon.discountPct / 100);
}
const freeShipThreshold = parseFloat(item.settingsMap['Free Shipping Threshold']) || 0;
const afterDiscount = subtotal - discountAmt;
const shippingCost = afterDiscount >= freeShipThreshold ? 0 : 10;
const taxRate = parseFloat((item.settingsMap['Tax Rate'] || '0').replace('%', '')) / 100;
const tax = afterDiscount * taxRate;
const grandTotal = afterDiscount + shippingCost + tax;

