const fs = require('fs');
const path = require('path');
const DATA_DIR = '/data';

function splitCSVLine(line) {
  const result = [];
  let cur = '';
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') {
      if (inQuotes && line[i + 1] === '"') { cur += '"'; i++; }
      else { inQuotes = !inQuotes; }
    } else if (c === ',' && !inQuotes) {
      result.push(cur); cur = '';
    } else {
      cur += c;
    }
  }
  result.push(cur);
  return result.map(v => v.trim());
}

function parseCSV(content) {
  if (!content) return [];
  const lines = content.split(/\r?\n/).filter(l => l.length > 0);
  if (lines.length === 0) return [];
  const headers = splitCSVLine(lines[0]);
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const vals = splitCSVLine(lines[i]);
    const obj = {};
    headers.forEach((h, idx) => { obj[h] = vals[idx] !== undefined ? vals[idx] : ''; });
    rows.push(obj);
  }
  return rows;
}

function toCSVValue(v) {
  v = (v === undefined || v === null) ? '' : String(v);
  if (v.includes(',') || v.includes('"') || v.includes('\n')) {
    v = '"' + v.replace(/"/g, '""') + '"';
  }
  return v;
}

function rowsToCSV(rows, headers) {
  const lines = [headers.join(',')];
  rows.forEach(r => { lines.push(headers.map(h => toCSVValue(r[h])).join(',')); });
  return lines.join('\n') + '\n';
}

function readTable(filename) {
  try {
    const filePath = path.join(DATA_DIR, filename);
    if (!fs.existsSync(filePath)) return { rows: [], headers: [] };
    const content = fs.readFileSync(filePath, 'utf8');
    const rows = parseCSV(content);
    const headers = rows.length > 0 ? Object.keys(rows[0]) : (content.split(/\r?\n/)[0] || '').split(',').map(h => h.trim());
    return { rows, headers };
  } catch (e) {
    return { rows: [], headers: [], error: e.message };
  }
}

function writeTable(filename, rows, headers) {
  try {
    const filePath = path.join(DATA_DIR, filename);
    fs.writeFileSync(filePath, rowsToCSV(rows, headers), 'utf8');
    return true;
  } catch (e) {
    return false;
  }
}

function appendLog(filename, row, headers) {
  try {
    const filePath = path.join(DATA_DIR, filename);
    let existed = fs.existsSync(filePath);
    const line = headers.map(h => toCSVValue(row[h])).join(',') + '\n';
    if (!existed) {
      fs.writeFileSync(filePath, headers.join(',') + '\n' + line, 'utf8');
    } else {
      fs.appendFileSync(filePath, line, 'utf8');
    }
    return true;
  } catch (e) {
    return false;
  }
}

